# Pure-Python3 verifier, no imports, no I/O, no filesystem, no network.
# Entry point: verify(witness). Raises AssertionError on any failed check
# (fail-closed). Returns the per-sequence report on success.

def verify(witness):
    BOUND = witness['bound']
    assert BOUND == 3**10, 'bound must be 3^10'
    SETS = witness['initial_sets']
    assert len(SETS) == 5, 'expected exactly five initial sets'
    CAND_PERIODS = [3**j for j in range(10)]
    results = []
    for idx in range(len(SETS)):
        A0 = SETS[idx]
        assert A0 == sorted(set(A0)), 'initial set %d not strictly increasing' % idx
        for a in A0:
            assert 0 <= a < BOUND, 'initial element out of range'
        S = list(A0)
        inS = set(A0)
        # --- greedy construction, fail-closed ---
        c = max(A0) + 1
        while c < BOUND:
            is_sum = False
            for a in S:
                if (c - a) in inS:
                    is_sum = True
                    break
            if not is_sum:
                S.append(c)
                inS.add(c)
            c += 1
        # --- check 1: 3-free ---
        for a in S:
            for b in S:
                assert (a + b) not in inS, '3-freeness violated: %d = %d + %d' % (a + b, a, b)
        # --- check 2: greedy completeness (fail-closed) ---
        for n in range(max(A0) + 1, BOUND):
            if n not in inS:
                found = False
                for a in S:
                    if a <= n and (n - a) in inS:
                        found = True
                        break
                assert found, 'greedy incomplete at %d' % n
        # --- check 3: indicator periodic with period 3^j, j <= 9 ---
        I = [0] * BOUND
        for a in S:
            assert I[a] == 0, 'duplicate element'
            I[a] = 1
        minimal_p = None
        for p in CAND_PERIODS:
            if p >= BOUND:
                break
            ok = True
            for n in range(BOUND - p):
                if I[n] != I[n + p]:
                    ok = False
                    break
            if ok:
                minimal_p = p
                break
        assert minimal_p is not None, 'no period 3^j for initial set %d' % idx
        results.append({'initial_set': A0, 'count': len(S), 'minimal_period': minimal_p})
    assert len(results) == 5
    return results
